queries.identity:
BEGIN READ ONLY;
SET LOCAL statement_timeout = '5000ms';
SELECT current_database() AS database, current_user AS effective_role, session_user AS session_role,
 current_setting('transaction_read_only') AS transaction_read_only,
 current_setting('default_transaction_read_only') AS default_transaction_read_only,
 current_setting('supabase.project_ref', true) AS configured_project_ref,
 (SELECT rolsuper FROM pg_roles WHERE rolname = current_user) AS role_superuser
; ROLLBACK;

queries.ledger:
BEGIN READ ONLY; SET LOCAL statement_timeout='5000ms'; SET LOCAL TIME ZONE 'UTC';
SELECT jsonb_build_object(
'roles',(SELECT jsonb_agg(jsonb_build_object('role',name,'created_at',"createdAt",'updated_at',"updatedAt") ORDER BY name) FROM public.roles WHERE name IN ('CUSTOMER','ADMIN')),
'ledger',(SELECT jsonb_agg(to_jsonb(m) ORDER BY started_at) FROM (SELECT migration_name,checksum,started_at,finished_at,rolled_back_at,applied_steps_count FROM public._prisma_migrations ORDER BY started_at LIMIT 101) m),
'summary',(SELECT jsonb_build_object('ledger_rows',count(*),'incomplete_rows',count(*) FILTER(WHERE finished_at IS NULL AND rolled_back_at IS NULL),'rolled_back_rows',count(*) FILTER(WHERE rolled_back_at IS NOT NULL),
'incident_window_rows',count(*) FILTER(WHERE started_at>=timestamptz '2026-10-13 12:31:00Z' AND started_at<timestamptz '2026-10-13 12:39:00Z' OR finished_at>=timestamptz '2026-10-13 12:31:00Z' AND finished_at<timestamptz '2026-10-13 12:39:00Z' OR rolled_back_at>=timestamptz '2026-10-13 12:31:00Z' AND rolled_back_at<timestamptz '2026-10-13 12:39:00Z')) FROM public._prisma_migrations)
) AS evidence; ROLLBACK;
